plot_habitat(build_habitat(scenarios[["TempOffset_ColdOnly_95percold"]]), exp_start_date = scenarios[["TempOffset_ColdOnly_95percold"]]$mindate + years(scenarios[["TempOffset_ColdOnly_95percold"]]$nyears_burnin))
